package com.lumix.api.gateway;
import java.util.Objects;
/** P29 deterministic admission gate；敏感 command 必須有 healthy input、剩餘 quota 和完全相同的 retry fingerprint。 */
public final class ApiAdmissionPolicy { public ApiAdmissionDecision evaluate(ApiRequestEvidence request,int remainingQuota,String existingPayloadFingerprint,String requestPayloadFingerprint){request=Objects.requireNonNull(request,"request");existingPayloadFingerprint=Objects.requireNonNull(existingPayloadFingerprint,"existingPayloadFingerprint");requestPayloadFingerprint=Objects.requireNonNull(requestPayloadFingerprint,"requestPayloadFingerprint");if(request.mode()==ApiContractMode.COMMAND&&request.health()!=ApiHealthState.HEALTHY)return ApiAdmissionDecision.HEALTH_NOT_TRUSTED_REJECTED;if(remainingQuota<1)return ApiAdmissionDecision.RATE_LIMIT_REJECTED;if(!existingPayloadFingerprint.isEmpty()&&!existingPayloadFingerprint.equals(requestPayloadFingerprint))return ApiAdmissionDecision.IDEMPOTENCY_CONFLICT_REJECTED;return ApiAdmissionDecision.ALLOWED;} }
